// Terrain height at a ground point, in metres; NaN where no loaded terrain covers the point.
export function heightAt(terrains, lon, lat) {
  for (const t of terrains) {
    const c = Math.round((lon - t.lon0) / t.dlon);
    const r = Math.round((t.lat0 - lat) / t.dlat);
    if (c >= 0 && r >= 0 && c < t.width && r < t.height) return t.heights[r * t.width + c];
  }
  return NaN;
}

