import { heightAt } from './terrain.js';

// Open 3D: a mesh of the terrain under the current view.
export function terrainMesh(terrains, view, size = 128) {
  const positions = new Float32Array(size * size * 3);
  for (let r = 0; r < size; r += 1) {
    for (let k = 0; k < size; k += 1) {
      const lon = view.west + ((view.east - view.west) * k) / (size - 1);
      const lat = view.north - ((view.north - view.south) * r) / (size - 1);
      const i = (r * size + k) * 3;
      positions[i] = lon;
      positions[i + 1] = lat;
      positions[i + 2] = heightAt(terrains, lon, lat);
    }
  }
  return { positions, size };
}
